export const messages: Record<Locale, Record<MessageKey, string>> = { en: EN, zh: ZH, ar: AR, es: ES, fr: FR };

/**
 * What `{name}` says when the owner has not confirmed a name yet.
 *
 * The assistant has no pronouns anywhere in the product (decided 2026-09-23):
 * the copy says the name the owner chose, and until there is one it says "your
 * assistant". It used to fall back to a product constant — Lily / 小雅 /
 * ياسمين — which put a name in front of the owner that nobody had chosen.
 *
 * Lower case on purpose: it is a phrase, not a name. `fillName` capitalises it
 * where a sentence starts, and `assistantName` hands out the capitalised form
 * for a label standing on its own.
 */
export const ASSISTANT_FALLBACK: Record<Locale, string> = { en: 'your assistant', zh: '你的助手', ar: 'مساعدك', es: 'tu asistente', fr: 'votre assistant' };

const capitalise = (s: string): string => s.charAt(0).toLocaleUpperCase() + s.slice(1);

/**
 * `{name}` filled in. A real name goes in as it is. The fallback phrase takes a
 * capital only at the start of the string or of a sentence — "Your assistant
 * knows 12 things", but "Teach your assistant" — so every sentence reads the
 * same whether the owner has named her yet or not. The value is compared
 * without case, so a caller holding the capitalised label gets the same result.
 */
function fillName(locale: Locale, s: string, name: string): string {
  const fallback = ASSISTANT_FALLBACK[locale];
  // Phase 9 (V1-008, V1-010) — the name joins the sentence the way its script
  // does. Chinese sets a Latin name off with spaces ("告诉 Lily。") but a Chinese
  // one, or 你的助手, runs on ("告诉你的助手。"); Arabic writes the prefix لـ apart
  // before a Latin name ("لـ Lily") and joined to an Arabic one ("لمساعدك").
  if (locale === 'zh' && !/[A-Za-z0-9]/.test(name)) s = s.replace(/ ?\{name\} ?/g, '{name}');
  // Phase 9 (V1-245) — and a Latin one is set off on both sides wherever Chinese
  // touches it, not only where a line happened to be written with spaces: the
  // card said "Lily 起草" and, one line below, "Lily正在处理".
  if (locale === 'zh' && /[A-Za-z0-9]/.test(name)) {
    s = s.replace(/([\u3400-\u9fff])\{name\}/g, '$1 {name}').replace(/\{name\}([\u3400-\u9fff])/g, '{name} $1');
  }
  if (locale === 'ar' && /^[\u0600-\u06FF]/.test(name)) s = s.replace(/لـ\s*\{name\}/g, 'ل{name}');
  if (name.toLocaleLowerCase() !== fallback.toLocaleLowerCase()) return s.split('{name}').join(name);
  return s.replace(/\{name\}/g, (_m, at: number) =>
    /^\s*$|[.!?]\s*$/.test(s.slice(0, at)) ? capitalise(fallback) : fallback);
}

/** A Chinese character or Chinese punctuation, for where a space between two goes. */
const HAN = '[\\p{Script=Han}\\u3000-\\u303F\\uFF00-\\uFFEF]';
const HAN_START = new RegExp(`^${HAN}`, 'u');
const HAN_END = new RegExp(`${HAN}$`, 'u');

/** Translate. Falls back to English, then the raw key. `{param}` interpolation. */
export function t(locale: Locale, key: MessageKey, params?: Record<string, string | number>): string {
  const table = messages[locale] ?? messages[DEFAULT_LOCALE];
  let s = table[key] ?? messages[DEFAULT_LOCALE][key] ?? key;
  const { name, ...rest } = params ?? {};
  // Phase 9 (V1-103) — Chinese sets a Latin value off with spaces and runs a
  // Chinese one on: "告诉 Omar Haddad 价格之后", but "告诉陈莉价格之后". The
  // catalogue writes the spaces; a space with Chinese on both sides goes.
  if (locale === 'zh') {
    for (const [k, v] of Object.entries(rest)) {
      const value = String(v);
      if (HAN_START.test(value)) s = s.replace(new RegExp(`(?<=${HAN}) \\{${k}\\}`, 'gu'), `{${k}}`);
      if (HAN_END.test(value)) s = s.replace(new RegExp(`\\{${k}\\} (?=${HAN})`, 'gu'), `{${k}}`);
    }
  }
  for (const [k, v] of Object.entries(rest)) s = s.split(`{${k}}`).join(String(v));
  // Any string may say {name} without every call site having to pass it.
  if (s.includes('{name}')) s = fillName(locale, s, name === undefined ? ASSISTANT_FALLBACK[locale] : String(name));
  return s;
}

/**
 * A sentence with a count in it, in the form its language gives that count
 * (`Intl.PluralRules`): English has two forms, Chinese one, Arabic six (zero,
 * one, two, few, many, other). Each counted sentence is six keys,
 * `<base>.<form>`, in every language, so the catalogue's keys stay the same
 * everywhere; a language fills the forms it does not use with its `other`.
 * `{n}` is the count as the language writes it.
 */
export function tn(locale: Locale, base: string, n: number, params?: Record<string, string | number>): string {
  const form = new Intl.PluralRules(locale).select(n);
  return t(locale, `${base}.${form}` as MessageKey, { ...params, n: new Intl.NumberFormat(locale === 'ar' ? 'ar-u-nu-latn' : locale).format(n) });
}

/** Owner-facing name for a country code, localized; the raw code if unknown. */
export function countryName(locale: Locale, code: string | null): string | null {
  if (!code) return null;
  const key = `country.${code}` as MessageKey;
  if (key in messages[DEFAULT_LOCALE]) return t(locale, key);
  // The positioning rewrite: the ten short names above were the export trade's
  // markets; every other country is named too, in the reader's language
  // (a customer from France had no country at all).
  // Only a real country: Intl names anything two letters long ("Unknown Region").
  if (!isCountryCode(code.toUpperCase())) return null;
  try {
    const name = new Intl.DisplayNames([REGION_TAG[locale]], { type: 'region' }).of(code.toUpperCase());
    return name && name !== code.toUpperCase() ? name : null;
  } catch {
    return null;
  }
}
const REGION_TAG: Record<Locale, string> = { en: 'en', zh: 'zh-CN', ar: 'ar', es: 'es', fr: 'fr' };

/** Localized order-status label; the raw code if unknown. */
export function orderStatusName(locale: Locale, status: string): string {
  const key = `order.status.${status}` as MessageKey;
  return key in messages[DEFAULT_LOCALE] ? t(locale, key) : status;
}

/** Localized capability name; the raw code if unknown. */
/** A claim the owner authorised, in their words. Unknown keys fall back to the key. */
export function claimName(locale: Locale, key: string): string {
  const k = `claim.${key}` as MessageKey;
  return k in messages[DEFAULT_LOCALE] ? t(locale, k) : key;
}

export function capabilityName(locale: Locale, code: string): string {
  const key = `capability.${code}` as MessageKey;
  return key in messages[DEFAULT_LOCALE] ? t(locale, key) : code;
}
